/**
 * The platform inside the Lexpad desktop app (macOS and Windows, Tauri).
 *
 * The desktop app runs this web app, built with `LEXPAD_TARGET=native`, in
 * its main window. It is the browser platform with four differences:
 *
 * - **The session belongs to the app's core, never to this page.** Every API
 *   call goes to the core over IPC (`api_fetch`), which sends it with the
 *   session it keeps in the system's credential store and refreshes it. No
 *   token ever reaches JavaScript, so nothing in this window can read one.
 * - **Signing in happens in the system browser** (RFC 8252, the connect page
 *   this web app serves at `/connect-desktop`), so no password is typed here
 *   and Google and Apple accounts, which refuse embedded web views, work.
 * - **No browser notifications or service worker**: the window is not a
 *   website. The daily reminder's plan goes to the core, which hands it to
 *   the system (`reminders`); the core shows the server's messages itself.
 *   A "tap" is the core asking this window to open a page (a word from the
 *   panel, a clicked notification), delivered through `push.onTap`.
 * - **Links leave for the system browser**: the core opens any page that is
 *   not this app's own there, and never inside the window.
 *
 * `@tauri-apps/api` is loaded on first use, so this file adds nothing to the
 * phone apps' bundle, and the browser build never contains it (`shell.ts`).
 */
import type {
  DesktopAccessibility,
  DesktopConnectFailure,
  DesktopHost,
  DesktopNotificationAccess,
  DesktopSettings,
  DesktopSettingsHost,
  Notice,
  Platform,
  Push,
  Reminders,
  ReminderStatus,
  WebPush,
} from './types.js';
import { platform as webPlatform } from './web.js';
import { pushPath } from './pushLink.js';
import type * as TauriCore from '@tauri-apps/api/core';

/** What the core sends back for a request, before its body. */
interface Head {
  status: number;
  headers: [string, string][];
}

/** One piece of a response body, the end of it, or a failure part-way. */
type BodyEvent = { kind: 'chunk'; data: string } | { kind: 'end' } | { kind: 'error' };

const FAILURES: ReadonlySet<string> = new Set(['cancelled', 'timeout', 'offline', 'error']);

function core(): Promise<typeof TauriCore> {
  return import('@tauri-apps/api/core');
}

function base64(bytes: Uint8Array): string {
  let text = '';
  const step = 0x8000;
  for (let i = 0; i < bytes.length; i += step) {
    text += String.fromCharCode(...bytes.subarray(i, i + step));
  }
  return btoa(text);
}

function bytesOf(encoded: string): Uint8Array<ArrayBuffer> {
  const text = atob(encoded);
  const out = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i += 1) out[i] = text.charCodeAt(i);
  return out;
}

/**
 * Sends a request through the core and gives back a real `Response`, whose
 * body streams as the core receives it (Lex's answers are a stream).
 */
export async function desktopFetch(url: string, init: RequestInit): Promise<Response> {
  const { invoke, Channel } = await core();
  // Request does the work of turning any body (JSON text, a multipart form)
  // into bytes and of writing the content type that goes with it.
  const request = new Request(url, init);
  const raw = new Uint8Array(await request.arrayBuffer());
  const headers: [string, string][] = [];
  request.headers.forEach((value, name) => {
    headers.push([name, value]);
  });

  let controller!: ReadableStreamDefaultController<Uint8Array>;
  const body = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c;
    },
  });
  const events = new Channel<BodyEvent>();
  events.onmessage = (event) => {
    if (event.kind === 'chunk') controller.enqueue(bytesOf(event.data));
    else if (event.kind === 'end') controller.close();
    else controller.error(new TypeError('the response was cut off'));
  };
  const abort = init.signal;
  if (abort?.aborted) throw new DOMException('aborted', 'AbortError');

  // A failure here is the network (or the core) failing, which is what a
  // rejected fetch means to the client.
  const head = await invoke<Head>('api_fetch', {
    request: {
      method: request.method,
      url: request.url,
      headers,
      body: raw.length === 0 ? null : base64(raw),
    },
    events,
  }).catch((cause: unknown) => {
    throw new TypeError(typeof cause === 'string' ? cause : 'the request could not be sent');
  });
  const nullBody = head.status === 204 || head.status === 304;
  return new Response(nullBody ? null : body, { status: head.status, headers: head.headers });
}

async function call<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  const { invoke } = await core();
  return invoke<T>(cmd, args);
}

const settings: DesktopSettingsHost = {
  read: () => call<DesktopSettings>('desktop_settings'),
  setShortcut: (accelerator) => call<string>('set_shortcut', { shortcut: accelerator }),
  setStartOnLogin: (on) => call<boolean>('set_start_on_login', { on }),
  setOpenOnLaunch: (on) => call<boolean>('set_open_on_launch', { on }),
  setOpenInBrowser: (on) => call<boolean>('set_open_in_browser', { on }),
  setQuickAddNotebook: (notebookId) => call<undefined>('set_notebook', { notebookId }),
  requestAccessibility: () => call<DesktopAccessibility>('accessibility', { request: true }),
  openAccessibilitySettings: () => call<undefined>('open_accessibility_settings'),
  setNotifications: (on) => call<DesktopNotificationAccess>('set_notifications', { on }),
  openNotificationSettings: () => call<undefined>('open_notification_settings'),
};

const STATUSES: ReadonlySet<string> = new Set(['scheduled', 'off', 'denied', 'unsupported']);

/**
 * The daily reminder, delivered by the system: the plan the app works out
 * (`sync/reminder.ts`) goes to the core, which hands it to macOS or Windows
 * so it arrives even while this window is shut.
 */
const reminders: Reminders = {
  async schedule(plan: readonly Notice[] | null): Promise<ReminderStatus> {
    const answer = await call<string>('schedule_reminders', {
      plan: plan === null ? null : plan.map((n) => ({ ...n, at: n.at.toISOString() })),
    }).catch(() => 'unsupported');
    return STATUSES.has(answer) ? (answer as ReminderStatus) : 'unsupported';
  },
};

const host: DesktopHost = {
  settings,
  fetch: desktopFetch,
  async signedIn() {
    const { invoke } = await core();
    return invoke<boolean>('main_signed_in');
  },
  async connect() {
    const { invoke } = await core();
    try {
      await invoke('connect');
    } catch (cause) {
      const word: DesktopConnectFailure =
        typeof cause === 'string' && FAILURES.has(cause) ? (cause as DesktopConnectFailure) : 'error';
      throw new Error(word, { cause });
    }
  },
  async cancelConnect() {
    const { invoke } = await core();
    await invoke('cancel_connect');
  },
  async disconnect() {
    const { invoke } = await core();
    await invoke('disconnect');
  },
  async openInBrowser(path) {
    const { invoke } = await core();
    await invoke('open_in_browser', { path });
  },
  onSessionChange(listener) {
    let stop: (() => void) | undefined;
    let stopped = false;
    void import('@tauri-apps/api/event').then(({ listen }) =>
      listen('session:changed', () => {
        listener();
      }).then((unlisten) => {
        if (stopped) unlisten();
        else stop = unlisten;
      }),
    );
    return () => {
      stopped = true;
      stop?.();
    };
  },
};

/**
 * No server push reaches the desktop app yet. A page the core asks this
 * window to open (a word from the add-a-word card) arrives as a tap, through
 * the same check as a notification's link.
 */
const push: Push = {
  available: false,
  token: () => Promise.resolve(null),
  enable: () => Promise.resolve(null),
  onToken: () => () => undefined,
  onTap(handler) {
    // An object, so the closures below see the change made when it stops.
    const life: { stopped: boolean; stop?: () => void } = { stopped: false };
    const stopped = (): boolean => life.stopped;
    void import('@tauri-apps/api/event').then(({ listen }) =>
      listen<string>('main:open', (event) => {
        handler(pushPath({ link: event.payload }));
      }).then(async (unlisten) => {
        if (stopped()) {
          unlisten();
          return;
        }
        life.stop = unlisten;
        // A page asked for before this window was listening (it was just
        // opened for a word, or by a clicked notification).
        const pending = await call<string | null>('main_take_pending').catch(() => null);
        if (pending !== null && !stopped()) handler(pushPath({ link: pending }));
      }),
    );
    return () => {
      life.stopped = true;
      life.stop?.();
    };
  },
  onReceive: () => () => undefined,
};

/** The window is not a website: no service worker, so no browser notifications. */
const webPush: WebPush = {
  support: () => Promise.resolve('unavailable'),
  subscription: () => Promise.resolve(null),
  subscribe: () => Promise.resolve({ status: 'failed' }),
  unsubscribe: () => Promise.resolve(),
};

export const platform: Platform = {
  ...webPlatform,
  push,
  webPush,
  reminders,
  desktop: host,
};
