/**
 * The platform facade. The app calls these interfaces and never touches a
 * browser or native API directly, so the same screens run in the browser
 * and inside the Capacitor shells. `web.ts` implements them here; the
 * mobile phase adds a native implementation of the same shape.
 */

/** Speech synthesis. */
export interface Tts {
  /** Speaks text in the given BCP-47 locale. Silent when unavailable. */
  speak(text: string, locale: string): void;
  cancel(): void;
  readonly available: boolean;
  /**
   * Whether the device has a voice for the locale's language. Optimistic
   * while the voice list is still loading, so a speaker is never hidden on
   * a guess; `onVoicesChange` fires once the answer is known.
   */
  canSpeak(locale: string): boolean;
  onVoicesChange(listener: () => void): () => void;
}

/**
 * Hearing a word instead of reading one typed.
 *
 * Two very different engines behind one shape: the browser's own recogniser
 * on the web, and the operating system's inside the shells. The app must not
 * know which, because the difference between them is exactly the thing that
 * produced a message about browser settings inside an Android app.
 */
export interface Speech {
  /**
   * Whether this device can listen at all. Asked rather than assumed: a
   * recogniser that exists but cannot run is the worst of the three states,
   * because the button looks ready and then fails.
   */
  available(): Promise<boolean>;
  /**
   * Listens once in the given BCP-47 locale. `onPartial` is called with what
   * is being heard so the button can show it is working. Resolves with the
   * final text, or an empty string when nothing was said.
   *
   * Rejects with a SpeechDenied when the microphone is refused, so a caller
   * can tell "you said no" from "it did not work".
   */
  listen(locale: string, onPartial: (text: string) => void): Promise<string>;
  /** Stops a listen in progress; the pending listen resolves with what it has. */
  stop(): void;
}

/** A microphone the person has refused, as opposed to one that failed. */
export class SpeechDenied extends Error {
  constructor() {
    super('speech: the microphone was refused');
    this.name = 'SpeechDenied';
  }
}

/** Short vibrations that confirm a grade without a sound. */
export interface Haptics {
  correct(): void;
  wrong(): void;
  success(): void;
}

/** Storage for values that must not sit in plain localStorage on native. */
export interface SecureStorage {
  get(key: string): Promise<string | null>;
  set(key: string, value: string): Promise<void>;
  remove(key: string): Promise<void>;
}

/** Small preferences that may live in localStorage everywhere. */
export interface Prefs {
  get(key: string): string | null;
  set(key: string, value: string): void;
  remove(key: string): void;
}

/** Handing a file to the user. */
export interface Share {
  file(name: string, mime: string, data: BlobPart): Promise<void>;
  text(value: string): Promise<void>;
  /**
   * Passes a link on: the system share sheet where there is one, the
   * clipboard where there is not. It reports which happened, because
   * "Copied" and "Sent" are different things to tell somebody.
   */
  link(url: string, title: string): Promise<'shared' | 'copied'>;
}

/** Online and offline transitions, feeding the sync worker. */
export interface Network {
  readonly online: boolean;
  onChange(listener: (online: boolean) => void): () => void;
}

/** Where the app is running, and how it was configured. */
export interface Env {
  /** True inside a native shell (the phone apps and the desktop app). */
  readonly embedded: boolean;
  readonly platform: 'web' | 'ios' | 'android' | 'desktop';
  readonly apiUrl: string;
  readonly appVersion: string;
  /** A stable per-install identifier, used for session bookkeeping. */
  readonly deviceId: string;
  readonly googleClientId: string;
  /** The Sign in with Apple Services ID; empty when Apple sign-in is not set up. */
  readonly appleClientId: string;
  readonly billingEnabled: boolean;
}

/** What became of a reminder request. */
export type ReminderStatus =
  /** A daily notification is scheduled. */
  | 'scheduled'
  /** No time is set, or it was just cleared. */
  | 'off'
  /** The person refused notification permission; the phone's settings hold the switch. */
  | 'denied'
  /** This host cannot deliver reminders: browsers get none yet. */
  | 'unsupported';

/** What a reminder notification says. */
export interface ReminderText {
  title: string;
  body: string;
}

/** One dated notification in the reminder plan. */
export interface Notice extends ReminderText {
  /** Stable within the plan, so the next plan replaces this one. */
  id: number;
  /** When it fires, as a local wall-clock moment. */
  at: Date;
}

/** The practice reminders, delivered by the host. */
export interface Reminders {
  /**
   * Replaces every reminder the host holds with this plan; null cancels them
   * all. Asks for permission when it has not been decided yet, and reports
   * what happened so a screen can say so.
   */
  schedule(plan: readonly Notice[] | null): Promise<ReminderStatus>;
}

/**
 * Notifications the server sends: come-back nudges, announcements and gifts.
 * They travel through Firebase Cloud Messaging, so only the native shells
 * have them; the daily reminder is not one of them and stays in `Reminders`,
 * because it must work offline and where Google's push service is blocked.
 */
export interface Push {
  /** False where the host cannot receive a push at all (every browser). */
  readonly available: boolean;
  /**
   * This install's push token, or null. Never asks for permission: a token
   * is read only when notifications are already allowed, so nothing here can
   * put a dialog in front of somebody who has not reached onboarding yet.
   */
  token(): Promise<string | null>;
  /**
   * Asks for notification permission if it has not been decided, then reads
   * the token. Only for a moment the learner chose: turning a reminder or
   * product news on. A refusal is not asked again.
   */
  enable(): Promise<string | null>;
  /** The token changed (or arrived late); returns a function that stops listening. */
  onToken(listener: (token: string) => void): () => void;
  /**
   * A notification was tapped. The handler gets an in-app path: the one the
   * notification carried when it is a safe one, Today otherwise.
   */
  onTap(handler: (path: string) => void): () => void;
  /**
   * A notification arrived while the app is open, so the bell can show it at
   * once instead of on the next visit to Today.
   */
  onReceive(listener: () => void): () => void;
}

/**
 * Where browser notifications stand on this device.
 * - `available`: the browser can subscribe here (Push API and a service worker).
 * - `needsInstall`: iPhone or iPad Safari in a tab, where Apple offers push
 *   only to a site added to the Home Screen.
 * - `unavailable`: no Push API, no service worker, or a native shell.
 */
export type WebPushSupport = 'available' | 'needsInstall' | 'unavailable';

/** What came of asking to turn browser notifications on. */
export type WebPushOutcome =
  | { status: 'subscribed'; subscription: Record<string, unknown> }
  /** The person refused, now or before; the browser's site settings hold the switch. */
  | { status: 'denied' }
  /** The browser could not subscribe (no push service, a network failure). */
  | { status: 'failed' };

/**
 * Notifications in a browser, through the standard Web Push protocol and the
 * PWA's service worker. No Firebase SDK and no new origin: the browser talks
 * to its own push service, which is not something the page's policy governs.
 * The native shells answer `unavailable`; they have `Push` instead.
 */
export interface WebPush {
  support(): Promise<WebPushSupport>;
  /**
   * The subscription this browser already holds, as `PushSubscription.toJSON()`
   * gives it, or null. Never prompts.
   */
  subscription(): Promise<Record<string, unknown> | null>;
  /**
   * Asks for notification permission (a moment the learner chose) and
   * subscribes with the server's VAPID public key, base64url. A subscription
   * made with a different key is replaced, because the browser refuses to
   * hold two.
   */
  subscribe(applicationServerKey: string): Promise<WebPushOutcome>;
  /** Drops this browser's subscription. Safe to call when there is none. */
  unsubscribe(): Promise<void>;
}

/** Moments in the app's life the host wants to know about. */
export interface Lifecycle {
  /** The first frame is painted: a shell hides its splash and wires its hooks. */
  ready(): void;
  /**
   * The app comes back to the foreground: a shell reports its resume, a
   * browser has nothing to add because the page's own visibility event covers
   * it. Returns a function that removes the listener.
   */
  onResume(listener: () => void): () => void;
}

/**
 * Sign-in a host can do natively. Browsers use the redirect flow instead,
 * so their implementation reports itself as unavailable.
 */
export interface NativeSignIn {
  readonly available: boolean;
  /** Runs Google Sign-In and returns the ID token for the given web client id. */
  googleIdToken(webClientId: string): Promise<string>;
}

/** Why connecting the desktop app did not finish. */
export type DesktopConnectFailure = 'cancelled' | 'timeout' | 'offline' | 'error';

/**
 * The Lexpad desktop app (macOS and Windows), which runs this web app in its
 * main window. Its core holds the session and is the only thing that ever
 * sees a token: every API call goes through `fetch` below, which the core
 * sends with the session it keeps in the system's credential store. Signing
 * in happens in the system browser (RFC 8252), so no password is ever typed
 * into this window and Google and Apple accounts work.
 */
export interface DesktopHost {
  /**
   * Sends one request to the API through the core, which adds the session.
   * Only addresses under the API's `/api/v1/` are accepted. A 401 means the
   * session has ended (the core has already tried a refresh).
   */
  fetch(url: string, init: RequestInit): Promise<Response>;
  /** Whether the core holds a session. */
  signedIn(): Promise<boolean>;
  /**
   * Opens the connect page in the system browser and waits until the learner
   * allows it there. Rejects with a `DesktopConnectFailure` message.
   */
  connect(): Promise<void>;
  /** Stops waiting for the browser. */
  cancelConnect(): Promise<void>;
  /** Signs this computer out: the core revokes its session and forgets it. */
  disconnect(): Promise<void>;
  /** Opens a page of the web app (a same-origin path) in the system browser. */
  openInBrowser(path: string): Promise<void>;
  /** The session changed from elsewhere in the app (its Settings window, the panel). */
  onSessionChange(listener: () => void): () => void;
  /** What only the desktop app has: its shortcut, permissions, start-up and notifications. */
  readonly settings: DesktopSettingsHost;
}

/** Whether the desktop app may read what is selected in other apps. */
export type DesktopAccessibility = 'granted' | 'missing' | 'not_needed';

/** Whether the desktop app may show notifications on this computer. */
export type DesktopNotificationAccess = 'granted' | 'denied' | 'not_determined' | 'unsupported';

/** The desktop app's own settings, as its core holds them. */
export interface DesktopSettings {
  os: 'macos' | 'windows';
  version: string;
  developmentBuild: boolean;
  /** As the global-shortcut plugin writes it: "CommandOrControl+Shift+L". */
  shortcut: string;
  startOnLogin: boolean;
  openOnLaunch: boolean;
  openInBrowser: boolean;
  /** The notebook the shortcut adds to; null is the account's default. */
  notebookId: string | null;
  accessibility: DesktopAccessibility;
  /** Accessibility was allowed in an earlier version and macOS dropped it with the update. */
  accessibilityStale: boolean;
  /** Notifications on this computer (the reminder and the server's messages). */
  notifications: boolean;
  notificationAccess: DesktopNotificationAccess;
}

/** The desktop section of Settings, talking to the app's core. */
export interface DesktopSettingsHost {
  read(): Promise<DesktopSettings>;
  /** Resolves with the shortcut now in use; rejects "taken" when another app holds it. */
  setShortcut(accelerator: string): Promise<string>;
  setStartOnLogin(on: boolean): Promise<boolean>;
  setOpenOnLaunch(on: boolean): Promise<boolean>;
  setOpenInBrowser(on: boolean): Promise<boolean>;
  setQuickAddNotebook(notebookId: string): Promise<void>;
  /** Asks macOS to list Lexpad under Accessibility, and says where it stands. */
  requestAccessibility(): Promise<DesktopAccessibility>;
  openAccessibilitySettings(): Promise<void>;
  /** On asks for permission when it was never asked; says where it stands. */
  setNotifications(on: boolean): Promise<DesktopNotificationAccess>;
  openNotificationSettings(): Promise<void>;
}

/** Everything the app needs from its host. */
export interface Platform {
  env: Env;
  tts: Tts;
  speech: Speech;
  haptics: Haptics;
  secure: SecureStorage;
  prefs: Prefs;
  share: Share;
  network: Network;
  reminders: Reminders;
  push: Push;
  webPush: WebPush;
  lifecycle: Lifecycle;
  signIn: NativeSignIn;
  /** Present only inside the desktop app. */
  desktop?: DesktopHost;
}

/** The shape a native shell may inject before the app boots. */
export interface ShellConfig {
  apiUrl?: string;
  platform?: 'ios' | 'android' | 'desktop';
  appVersion?: string;
  deviceId?: string;
}
