/**
 * What Android's recogniser calls an error, and what it actually means.
 *
 * Android reports "heard nothing" as an error, and it is not one: it is the
 * commonest outcome of tapping a microphone and then thinking about it.
 * Painting that red is what made the app look broken on a phone that was
 * working perfectly — the button said "that did not come through, try a
 * little closer to the microphone" the instant it was pressed.
 *
 * The strings come from the plugin's own `getErrorText`, so this is the
 * whole list rather than a guess at it. They are matched exactly: a
 * substring match on "no match" would also swallow a future message that
 * happened to contain it.
 */

/**
 * Nothing was said. Not a failure, and not worth a word on screen.
 *
 * Only the two codes that actually mean silence are here. The plugin's
 * catch-all, "Didn't understand, please try again.", is deliberately not:
 * it is the bucket for every error code the plugin does not recognise, and
 * on a device it arrived five milliseconds after the tap — a recogniser
 * that never listened at all. Calling that silence would hide a real fault
 * behind a button that appears to do nothing.
 */
const SILENCE = new Set(['No match', 'No speech input']);

/** The microphone was refused, which is an answer rather than a fault. */
const REFUSED = new Set(['Insufficient permissions', 'Missing permission']);

/** What a rejected listen means. */
export type SpeechOutcome = 'silence' | 'refused' | 'failed';

/** Reads the recogniser's error message. */
export function outcomeOf(message: string): SpeechOutcome {
  if (SILENCE.has(message)) return 'silence';
  if (REFUSED.has(message)) return 'refused';
  return 'failed';
}

/**
 * Errors that mean the recogniser never got going, rather than that it
 * listened and failed.
 *
 * The plugin destroys its recogniser and builds a new one on every listen,
 * then calls `startListening` on it straight away. Binding to the system's
 * recognition service is an inter-process call the plugin does not wait
 * for, so on a cold service the request arrives before anything is
 * listening and Android answers within a few milliseconds — which is
 * exactly what a person sees as "it failed the instant I tapped it, and
 * then the next tap worked".
 *
 * - `Client side error` is ERROR_CLIENT, the usual answer from a recogniser
 *   that is not bound yet.
 * - `RecognitionService busy` is ERROR_RECOGNIZER_BUSY: the session before
 *   this one has not finished being torn down.
 * - `Didn't understand, please try again.` is the plugin's catch-all for
 *   every code it does not name, and ERROR_SERVER_DISCONNECTED — the
 *   commonest form of this on Android 12 and later — lands in it.
 *
 * None of the three is a considered answer about what was said, so each is
 * worth one more go before anybody is told it did not work.
 */
const NOT_READY = new Set([
  'Client side error',
  'RecognitionService busy',
  "Didn't understand, please try again.",
]);

/** Whether this failure deserves a second, quiet attempt. */
export function worthRetrying(message: string): boolean {
  return NOT_READY.has(message);
}
