/** The browser implementation of the platform facade. */
import type {
  Env,
  Haptics,
  Lifecycle,
  NativeSignIn,
  Network,
  Platform,
  Prefs,
  Push,
  Reminders,
  WebPush,
  WebPushSupport,
  SecureStorage,
  Share,
  ShellConfig,
  Speech,
  Tts,
} from './types.js';
import { SpeechDenied } from './types.js';
import { pushPath } from './pushLink.js';

declare global {
  interface Window {
    __LEXPAD_EMBEDDED?: boolean;
    __LEXPAD_CONFIG?: ShellConfig;
  }
}

const DEVICE_ID_KEY = 'wb.deviceId';

/** localStorage that never throws, because private mode and iframes do. */
export const prefs: Prefs = {
  get(key) {
    try {
      return localStorage.getItem(key);
    } catch {
      return null;
    }
  },
  set(key, value) {
    try {
      localStorage.setItem(key, value);
    } catch {
      /* nothing we can do, and nothing important is lost */
    }
  },
  remove(key) {
    try {
      localStorage.removeItem(key);
    } catch {
      /* as above */
    }
  },
};

export function deviceId(): string {
  const existing = prefs.get(DEVICE_ID_KEY);
  if (existing) return existing;
  const fresh = crypto.randomUUID();
  prefs.set(DEVICE_ID_KEY, fresh);
  return fresh;
}

function readEnv(): Env {
  const shell = window.__LEXPAD_CONFIG ?? {};
  return {
    embedded: window.__LEXPAD_EMBEDDED === true || shell.platform !== undefined,
    platform: shell.platform ?? 'web',
    // A shell injects its own API host; on the web an empty base means
    // same-origin, which keeps the refresh cookie working.
    apiUrl: shell.apiUrl ?? import.meta.env.VITE_API_URL ?? '',
    appVersion: shell.appVersion ?? import.meta.env.VITE_APP_VERSION ?? 'dev',
    deviceId: shell.deviceId ?? deviceId(),
    googleClientId: import.meta.env.VITE_GOOGLE_CLIENT_ID ?? '',
    appleClientId: import.meta.env.VITE_APPLE_CLIENT_ID ?? '',
    billingEnabled: import.meta.env.VITE_BILLING_ENABLED === 'true',
  };
}

/**
 * The utterance currently playing. Chrome garbage-collects an utterance
 * nothing references and the speech stops with it, so the newest one is
 * held here until the next replaces it.
 */
let current: SpeechSynthesisUtterance | undefined;

/**
 * Languages the browser has a voice for, as lowercase primary tags; undefined
 * until the list has arrived. Chrome delivers it asynchronously and empty
 * lists mean "not yet", not "none".
 */
let voiceLanguages: Set<string> | undefined;
const voiceListeners = new Set<() => void>();

function languageOf(locale: string): string {
  return locale.toLowerCase().split(/[-_]/)[0] ?? '';
}

function readVoices(): void {
  const voices = window.speechSynthesis.getVoices();
  if (voices.length === 0) return;
  voiceLanguages = new Set(voices.map((voice) => languageOf(voice.lang)));
  for (const listener of voiceListeners) listener();
}

if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
  try {
    readVoices();
    window.speechSynthesis.addEventListener('voiceschanged', readVoices);
  } catch {
    /* no voice list: speakers stay visible and speaking is silent */
  }
}

/**
 * The browser's own recogniser, under either of the two names it ships as.
 * Typed here rather than pulled from the DOM library, which does not carry
 * it: it is a living standard that browsers implement and TypeScript does
 * not yet describe.
 */
interface Recogniser extends EventTarget {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  maxAlternatives: number;
  start: () => void;
  stop: () => void;
  abort: () => void;
  onresult: ((event: RecognitionEvent) => void) | null;
  onerror: ((event: { error: string }) => void) | null;
  onend: (() => void) | null;
}

interface RecognitionEvent {
  results: ArrayLike<ArrayLike<{ transcript: string }> & { isFinal: boolean }>;
}

type RecogniserClass = new () => Recogniser;

function recogniserClass(): RecogniserClass | undefined {
  if (typeof window === 'undefined') return undefined;
  const scope = window as unknown as {
    SpeechRecognition?: RecogniserClass;
    webkitSpeechRecognition?: RecogniserClass;
  };
  return scope.SpeechRecognition ?? scope.webkitSpeechRecognition;
}

let listening: Recogniser | undefined;

/**
 * Speech on the web.
 *
 * Firefox ships no recogniser at all, so `available` answers false and the
 * button says so rather than appearing and failing.
 */
const speech: Speech = {
  available: () => Promise.resolve(recogniserClass() !== undefined),

  listen: (locale, onPartial) =>
    new Promise<string>((resolve, reject) => {
      const Recognition = recogniserClass();
      if (Recognition === undefined) {
        resolve('');
        return;
      }
      listening?.abort();

      const recogniser = new Recognition();
      recogniser.lang = locale;
      recogniser.continuous = false;
      recogniser.interimResults = true;
      recogniser.maxAlternatives = 1;

      let said = '';
      // The last words shown on screen but not yet settled. Somebody who
      // taps stop while reading them has seen a word and means to keep it;
      // throwing it away because the recogniser had not finished agreeing
      // with itself is the app losing something the person could see.
      let showing = '';
      let refused = false;
      recogniser.onresult = (event) => {
        let interim = '';
        for (const result of Array.from(event.results)) {
          const text = result[0]?.transcript ?? '';
          if (result.isFinal) said += text;
          else interim += text;
        }
        showing = (said + interim).trim();
        onPartial(showing);
      };
      recogniser.onerror = (event) => {
        // "aborted" is us stopping it and "no-speech" is somebody changing
        // their mind: neither is a refusal and neither is a failure.
        refused = event.error === 'not-allowed' || event.error === 'service-not-allowed';
      };
      recogniser.onend = () => {
        listening = undefined;
        if (refused) reject(new SpeechDenied());
        else resolve(said.trim() === '' ? showing : said.trim());
      };

      listening = recogniser;
      try {
        recogniser.start();
      } catch {
        listening = undefined;
        resolve('');
      }
    }),

  stop: () => {
    listening?.stop();
  },
};

const tts: Tts = {
  available: typeof window !== 'undefined' && 'speechSynthesis' in window,
  canSpeak(locale) {
    if (!this.available) return false;
    return voiceLanguages === undefined || voiceLanguages.has(languageOf(locale));
  },
  onVoicesChange(listener) {
    voiceListeners.add(listener);
    return () => {
      voiceListeners.delete(listener);
    };
  },
  speak(text, locale) {
    if (!this.available || text.trim() === '') return;
    try {
      const synth = window.speechSynthesis;
      // Exactly what the prototype does, because it is what works across
      // browsers: no explicit voice — Chrome lists network voices first and
      // those can play nothing offline — just the language, a slightly slower
      // rate, and speak in the same tick as the cancel.
      // Cutting off our own earlier utterance can leave Chrome's engine
      // paused, and a paused engine accepts speak() and plays nothing.
      const interrupting = current !== undefined || synth.speaking;
      synth.cancel();
      if (interrupting && synth.paused) synth.resume();
      const utterance = new SpeechSynthesisUtterance(text.replace(/\s*\/\s*/g, ' or '));
      utterance.lang = locale;
      utterance.rate = 0.9;
      current = utterance;
      synth.speak(utterance);
    } catch {
      /* a missing voice is not worth interrupting practice for */
    }
  },
  cancel() {
    if (!this.available) return;
    window.speechSynthesis.cancel();
    current = undefined;
  },
};

/*
 * The DOM typings declare `vibrate` and `canShare` as always present. Real
 * browsers disagree: iOS Safari has neither. These aliases make the optional
 * reality visible to the type checker instead of hiding it behind a cast at
 * every call site.
 */
type NavigatorWithOptionalVibrate = Omit<Navigator, 'vibrate'> & {
  vibrate?: (pattern: number | number[]) => boolean;
};
type NavigatorWithOptionalShare = Omit<Navigator, 'canShare' | 'share'> & {
  canShare?: (data?: ShareData) => boolean;
  share?: (data?: ShareData) => Promise<void>;
};

function vibrate(pattern: number | number[]): void {
  const nav: NavigatorWithOptionalVibrate = navigator;
  try {
    nav.vibrate?.(pattern);
  } catch {
    /* a device without a motor is not an error */
  }
}

const haptics: Haptics = {
  correct: () => {
    vibrate(12);
  },
  wrong: () => {
    vibrate([18, 40, 18]);
  },
  success: () => {
    vibrate([10, 30, 10, 30, 24]);
  },
};

/**
 * On the web the refresh token lives in an httpOnly cookie, so there is
 * nothing secret to store. The native implementation uses the Keychain and
 * Keystore instead.
 */
const secure: SecureStorage = {
  get: (key) => Promise.resolve(prefs.get(`wb.secure.${key}`)),
  set: (key, value) => {
    prefs.set(`wb.secure.${key}`, value);
    return Promise.resolve();
  },
  remove: (key) => {
    prefs.remove(`wb.secure.${key}`);
    return Promise.resolve();
  },
};

const share: Share = {
  async file(name, mime, data) {
    const blob = new Blob([data], { type: mime });
    const file = new File([blob], name, { type: mime });
    const nav: NavigatorWithOptionalShare = navigator;
    // The share sheet is the better home on a phone. Desktop browsers mostly
    // say they can share a file and then refuse, so any failure other than
    // the user closing the sheet falls through to a download.
    if (nav.canShare?.({ files: [file] }) && nav.share) {
      try {
        await nav.share({ files: [file], title: name });
        return;
      } catch (cause) {
        if (cause instanceof DOMException && cause.name === 'AbortError') return;
      }
    }
    download(blob, name);
  },
  async text(value) {
    await navigator.clipboard.writeText(value);
  },
  async link(url, title) {
    const nav: NavigatorWithOptionalShare = navigator;
    // A phone shares; a desktop browser usually cannot, and one that says
    // it can often refuses, so anything but the user closing the sheet
    // falls through to the clipboard.
    if (nav.share) {
      try {
        await nav.share({ url, title });
        return 'shared';
      } catch (cause) {
        if (cause instanceof DOMException && cause.name === 'AbortError') return 'shared';
      }
    }
    await navigator.clipboard.writeText(url);
    return 'copied';
  },
};

/**
 * Saves a blob through a temporary link. The link has to be in the document
 * for every browser to honour the click, and the object URL must outlive the
 * click: revoking it at once makes Chrome drop the download silently.
 */
function download(blob: Blob, name: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = name;
  anchor.rel = 'noopener';
  anchor.style.display = 'none';
  document.body.appendChild(anchor);
  anchor.click();
  window.setTimeout(() => {
    anchor.remove();
    URL.revokeObjectURL(url);
  }, 10_000);
}

const network: Network = {
  get online() {
    return navigator.onLine;
  },
  onChange(listener) {
    const up = (): void => {
      listener(true);
    };
    const down = (): void => {
      listener(false);
    };
    window.addEventListener('online', up);
    window.addEventListener('offline', down);
    return () => {
      window.removeEventListener('online', up);
      window.removeEventListener('offline', down);
    };
  },
};

/** The platform this build runs on. */
/** Browsers get no scheduled reminder yet; the setting still syncs for the shells. */
const reminders: Reminders = {
  // Browsers cannot schedule a notification for tomorrow; the shells can.
  schedule: (plan) => Promise.resolve(plan === null ? 'off' : 'unsupported'),
};

/**
 * The Firebase push of the shells does not exist in a browser. Firebase's web
 * SDK is deliberately not part of this build: it would add weight to every
 * learner's download and an origin to the security policy. Browsers get
 * notifications through `webPush` below instead, over the standard protocol.
 *
 * A tap on a browser notification is still reported here, so the app has one
 * place that follows a tapped notification: the service worker
 * (`public/push-sw.js`) focuses an open tab and posts it the link.
 */
const push: Push = {
  available: false,
  token: () => Promise.resolve(null),
  enable: () => Promise.resolve(null),
  onToken: () => () => undefined,
  onTap(handler) {
    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return () => undefined;
    const listener = (event: MessageEvent): void => {
      const data: unknown = event.data;
      if (
        typeof data === 'object' &&
        data !== null &&
        (data as { type?: unknown }).type === PUSH_TAP_MESSAGE
      ) {
        handler(pushPath(data));
      }
    };
    navigator.serviceWorker.addEventListener('message', listener);
    return () => {
      navigator.serviceWorker.removeEventListener('message', listener);
    };
  },
  onReceive(listener) {
    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return () => undefined;
    const onMessage = (event: MessageEvent): void => {
      const data: unknown = event.data;
      if (
        typeof data === 'object' &&
        data !== null &&
        (data as { type?: unknown }).type === PUSH_RECEIVED_MESSAGE
      ) {
        listener();
      }
    };
    navigator.serviceWorker.addEventListener('message', onMessage);
    return () => {
      navigator.serviceWorker.removeEventListener('message', onMessage);
    };
  },
};

/** What the service worker posts to open tabs when a notification arrives. Also written in `public/push-sw.js`. */
export const PUSH_RECEIVED_MESSAGE = 'lexpad:push-received';

/**
 * The message the service worker posts to an open tab when one of its
 * notifications is tapped. The same string is written in `public/push-sw.js`,
 * which is a plain script and cannot import it.
 */
export const PUSH_TAP_MESSAGE = 'lexpad:push-tap';

/** iPhone and iPad, including an iPad that reports itself as a Mac. */
function isAppleMobile(): boolean {
  const nav = navigator as Navigator & { standalone?: boolean };
  return (
    /iPad|iPhone|iPod/.test(nav.userAgent) || (nav.userAgent.includes('Macintosh') && nav.maxTouchPoints > 1)
  );
}

/** Running as an installed app rather than in a browser tab. */
function isStandalone(): boolean {
  const nav = navigator as Navigator & { standalone?: boolean };
  if (nav.standalone === true) return true;
  try {
    return window.matchMedia('(display-mode: standalone)').matches;
  } catch {
    return false;
  }
}

/** The service worker's registration, when there is one to subscribe through. */
async function workerRegistration(): Promise<ServiceWorkerRegistration | undefined> {
  if (!('serviceWorker' in navigator)) return undefined;
  try {
    return await navigator.serviceWorker.getRegistration();
  } catch {
    return undefined;
  }
}

/** A VAPID key arrives as base64url; the Push API takes its bytes. */
export function keyBytes(base64url: string): Uint8Array<ArrayBuffer> {
  const padded = base64url
    .replace(/-/g, '+')
    .replace(/_/g, '/')
    .padEnd(Math.ceil(base64url.length / 4) * 4, '=');
  const binary = atob(padded);
  const bytes = new Uint8Array(new ArrayBuffer(binary.length));
  for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function sameBytes(left: ArrayBuffer | null, right: Uint8Array): boolean {
  if (left?.byteLength !== right.byteLength) return false;
  const view = new Uint8Array(left);
  return view.every((byte, index) => byte === right[index]);
}

function asJson(subscription: PushSubscription): Record<string, unknown> {
  return subscription.toJSON() as Record<string, unknown>;
}

const webPush: WebPush = {
  async support(): Promise<WebPushSupport> {
    if (typeof window === 'undefined' || typeof navigator === 'undefined') return 'unavailable';
    // Apple offers push only to a site on the Home Screen; in a Safari tab
    // there is no PushManager at all, so this is asked before that is.
    if (isAppleMobile() && !isStandalone()) return 'needsInstall';
    if (!('PushManager' in window) || !('Notification' in window)) return 'unavailable';
    return (await workerRegistration()) === undefined ? 'unavailable' : 'available';
  },

  async subscription() {
    if (typeof window === 'undefined' || !('Notification' in window) || !('PushManager' in window))
      return null;
    // A subscription whose permission was taken away delivers nothing.
    if (Notification.permission !== 'granted') return null;
    const registration = await workerRegistration();
    if (registration === undefined) return null;
    try {
      const existing = await registration.pushManager.getSubscription();
      return existing === null ? null : asJson(existing);
    } catch {
      return null;
    }
  },

  async subscribe(applicationServerKey) {
    if (!('Notification' in window) || !('PushManager' in window)) return { status: 'failed' };
    const registration = await workerRegistration();
    if (registration === undefined) return { status: 'failed' };
    let permission = Notification.permission;
    if (permission === 'default') {
      try {
        permission = await Notification.requestPermission();
      } catch {
        return { status: 'failed' };
      }
    }
    if (permission !== 'granted') return { status: 'denied' };
    try {
      const key = keyBytes(applicationServerKey);
      const existing = await registration.pushManager.getSubscription();
      if (existing !== null) {
        if (sameBytes(existing.options.applicationServerKey, key)) {
          return { status: 'subscribed', subscription: asJson(existing) };
        }
        // Made with a key the server no longer signs with: it can never
        // deliver again, and the browser will not hold a second one beside it.
        await existing.unsubscribe();
      }
      const fresh = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: key,
      });
      return { status: 'subscribed', subscription: asJson(fresh) };
    } catch {
      return { status: 'failed' };
    }
  },

  async unsubscribe() {
    const registration = await workerRegistration();
    if (registration === undefined) return;
    try {
      const existing = await registration.pushManager.getSubscription();
      await existing?.unsubscribe();
    } catch {
      // Nothing held, or the browser lost it already: either way it is gone.
    }
  },
};

const lifecycle: Lifecycle = {
  ready() {
    // Nothing to hide or wire in a browser.
  },
  onResume() {
    // The document's visibility event already fires when a tab is shown again.
    return () => undefined;
  },
};

/** Browsers sign in with Google through the redirect flow; nothing native here. */
const signIn: NativeSignIn = {
  available: false,
  googleIdToken: () => Promise.reject(new Error('native sign-in is not available in a browser')),
};

export const platform: Platform = {
  env: readEnv(),
  tts,
  speech,
  haptics,
  secure,
  prefs,
  share,
  network,
  reminders,
  push,
  webPush,
  lifecycle,
  signIn,
};
